const httpItem = $('جلب بيانات النظام (Supabase)').first().json;
const row = Array.isArray(httpItem) ? httpItem[0] : httpItem;
const data = row && row.data ? row.data : row;
const agentsEmails = $('إعدادات المستلمين (عدّل هنا)').first().json.agentsEmails;

const todayD = new Date();
const to = todayD.toISOString().slice(0, 10);
const fromD = new Date(todayD); fromD.setDate(fromD.getDate() - 6);
const from = fromD.toISOString().slice(0, 10);

// معدل الحضور لكل طالب خلال الأسبوع
const students = data.students || [];
const attRows = students.map(s => {
  let absent = 0, excused = 0, late = 0, total = 0, present = 0;
  Object.keys(data.attendance || {}).forEach(k => {
    const d = k.split('|')[0];
    if (d < from || d > to) return;
    const r = data.attendance[k][s.id];
    if (!r) return;
    total++;
    if (r.day === 'absent') absent++;
    else if (r.day === 'excused') excused++;
    else if (r.day === 'late') { late++; present++; }
    else if (r.day === 'present') present++;
  });
  const rate = total ? Math.round((present / total) * 100) : 100;
  return { name: s.name, grade: s.grade, section: s.section, absent, excused, late, rate };
}).filter(r => r.absent + r.excused + r.late > 0)
  .sort((a, b) => a.rate - b.rate);

// الفاقد التعليمي لكل موظف خلال الأسبوع
const inRange = (data.teacherAbsences || []).filter(a => a.date >= from && a.date <= to);
const byEmp = {};
inRange.forEach(a => {
  if (!byEmp[a.empName]) byEmp[a.empName] = { fullDays: 0, late: 0, perm: 0, missing: 0, covered: 0 };
  const b = byEmp[a.empName];
  if (a.type === 'غياب يوم كامل') b.fullDays++;
  if (a.type === 'تأخر صباحي') b.late++;
  if (a.type === 'استئذان خروج مبكر') b.perm++;
  b.missing += (a.missing || 0);
  b.covered += Object.values(a.covers || {}).filter(Boolean).length;
});
const lostRows = Object.keys(byEmp).map(name => {
  const b = byEmp[name];
  const net = Math.max(0, b.missing - b.covered);
  const rate = b.missing ? Math.round((b.covered / b.missing) * 100) : 0;
  return { name, ...b, net, rate };
}).sort((a, b) => b.net - a.net);

const attTable = `<h3>معدل الحضور الأسبوعي (${from} إلى ${to}) - الطلاب الأكثر غياباً</h3>
<table border="1" cellpadding="6" cellspacing="0" style="border-collapse:collapse;font-family:sans-serif">
<tr><th>الطالب</th><th>الصف/الفصل</th><th>غياب</th><th>بعذر</th><th>تأخر</th><th>نسبة الحضور</th></tr>
${attRows.slice(0, 25).map(r => `<tr><td>${r.name}</td><td>${r.grade}/${r.section}</td><td>${r.absent}</td><td>${r.excused}</td><td>${r.late}</td><td>${r.rate}%</td></tr>`).join('')}
</table>`;

const lostTable = `<h3>تقرير الفاقد التعليمي الأسبوعي</h3>
<table border="1" cellpadding="6" cellspacing="0" style="border-collapse:collapse;font-family:sans-serif">
<tr><th>الموظف</th><th>غياب كامل</th><th>تأخر</th><th>استئذان</th><th>حصص مفقودة</th><th>حصص مسدودة</th><th>فاقد فعلي</th><th>نسبة السد</th></tr>
${lostRows.map(r => `<tr><td>${r.name}</td><td>${r.fullDays}</td><td>${r.late}</td><td>${r.perm}</td><td>${r.missing}</td><td>${r.covered}</td><td>${r.net}</td><td>${r.rate}%</td></tr>`).join('')}
</table>`;

const html = `<h2>التقرير الأسبوعي - ${data.settings ? data.settings.schoolName : ''}</h2>${attTable}${lostTable}`;

return [{ json: { html, from, to, agentsEmails, schoolName: data.settings ? data.settings.schoolName : '' } }];
